package com.blog.service.impl; import com.blog.dto.CommentDtos.*; import com.blog.entity.*; import com.blog.exception.ApiExceptions.*; import com.blog.mapper.BlogMapper; import com.blog.repository.*; import com.blog.service.BlogServices.CommentService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class CommentServiceImpl implements CommentService {private final CommentRepository comments;private final PostRepository posts;private final UserRepository users;private final BlogMapper mapper; public CommentResponse create(Long postId,CommentRequest r,String email){var parent=r.parentCommentId()==null?null:comments.findById(r.parentCommentId()).orElseThrow(()->new ResourceNotFoundException("Parent comment not found"));if(parent!=null&&!parent.getPost().getId().equals(postId))throw new BadRequestException("Parent comment belongs to another post");var c=Comment.builder().content(r.content()).post(posts.findById(postId).orElseThrow(()->new ResourceNotFoundException("Post not found"))).user(user(email)).parentComment(parent).build();return mapper.comment(comments.save(c));} @Transactional(readOnly=true) public List<CommentResponse> findByPost(Long postId){if(!posts.existsById(postId))throw new ResourceNotFoundException("Post not found");return comments.findByPostIdAndParentCommentIsNullOrderByCreatedAtAsc(postId).stream().map(mapper::comment).toList();} public void delete(Long id,String email){var c=comments.findById(id).orElseThrow(()->new ResourceNotFoundException("Comment not found"));var u=user(email);if(u.getRole()!=Role.ADMIN&&!c.getUser().getId().equals(u.getId()))throw new UnauthorizedException("You do not own this comment");comments.delete(c);}private User user(String email){return users.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found"));}}
